#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum CcaiServiceProvider {
    /// No specified provider or placeholder
    NoCcaiServiceProvider = 0,
    /// ONDEWO provider for CCAI service services
    /// <a href="<https://www.ondewo.com/">ONDEWO</a>>
    Ondewo = 1,
    /// Google as the CCAI service provider, utilizing Google&apos;s conversational AI capabilities
    /// <a href="<https://deepmind.google/technologies/gemini/">Google> Gemini</a>
    GoogleGemini = 2,
    /// Microsoft Azure as the CCAI service provider, using Microsoft&apos;s Azure cognitive services
    /// <a href="<https://azure.microsoft.com/en-us/products/cognitive-services/openai-service/">Azure> OpenAI</a>
    MicrosoftAzureOpenai = 3,
    /// Microsoft AutoGen as the CCAI service provider
    /// <a href="<https://github.com/microsoft/autogen">AutoGen</a>>
    MicrosoftAutogen = 4,
    /// Ollama as the CCAI service provider, typically associated with specific OLLAMA AI tools
    /// <a href="<https://github.com/ollama/ollama">Ollama</a>>
    Ollama = 5,
    /// OpenAI as the CCAI service provider, commonly used for models such as GPT
    /// <a href="<https://openai.com/">OpenAI</a>>
    Openai = 6,
    /// Anthropic as the CCAI service provider, used with AI models from Anthropic
    /// <a href="<https://www.anthropic.com/">Anthropic</a>>
    Anthropic = 7,
    /// Hugging Face as the CCAI service provider, often used for open-source NLP models
    /// <a href="<https://huggingface.co/">Hugging> Face</a>
    Huggingface = 8,
    /// IBM as the CCAI service provider, such as IBM Watson for conversational AI
    /// <a href="<https://www.ibm.com/watson">IBM> Watson</a>
    Ibm = 9,
    /// Haystack as the CCAI service provider, e.g., for question answering and conversations
    /// <a href="<https://github.com/deepset-ai/haystack">Haystack</a>>
    Haystack = 10,
    /// LangChain as the CCAI service provider
    /// <a href="<https://github.com/langchain-ai/langchain">LangChain</a>>
    Langchain = 11,
    /// Amazon AWS as the CCAI service provider, using Amazon&apos;s AI/ML services
    /// <a href="<https://aws.amazon.com/machine-learning/">AWS> AI Services</a>
    Amazon = 12,
    /// Mistral as the CCAI service provider, using Mistral&apos;s services
    /// <a href="<https://mistral.ai/">Mistral</a>>
    Mistral = 13,
    /// DuckDuckGo Websearch API
    /// <a href="<https://duckduckgo.com/api">DuckDuckGo> API</a>
    Duckduckgo = 14,
    /// Google PSE Websearch API
    /// <a href="<https://programmablesearchengine.google.com/">Google> Programmable Search Engine</a>
    GooglePse = 15,
    /// Jina Websearch API
    /// <a href="<https://github.com/jina-ai/jina">Jina> AI</a>
    Jina = 16,
    /// Tavily Websearch API
    /// <a href="<https://tavily.com/">Tavily> API</a>
    Tavily = 17,
    /// ElasticSearch vector database service
    /// <a href="<https://www.elastic.co/">ElasticSearch</a>>
    Elasticsearch = 18,
    /// Milvus vector database service
    /// <a href="<https://milvus.io/">Milvus</a>>
    Milvus = 19,
    /// Qdrant vector database service
    /// <a href="<https://qdrant.tech/">Qdrant</a>>
    Qdrant = 20,
    /// Chroma vector database service
    /// <a href="<https://github.com/chroma-core/chroma">ChromaDB</a>>
    Chroma = 21,
    /// Google CCAI service provider
    /// <a href="<https://cloud.google.com/ai">Google> Cloud AI</a>
    Google = 22,
    /// Microsoft CCAI service provider
    /// <a href="<https://www.microsoft.com/en-us/ai">Microsoft> AI</a>
    Microsoft = 23,
    /// Deepgram as the CCAI service provider for speech processing
    /// <a href="<https://deepgram.com/">Deepgram</a>>
    Deepgram = 24,
    /// ElevenLabs as the CCAI service provider for voice synthesis
    /// <a href="<https://elevenlabs.io/">ElevenLabs</a>>
    Elevenlabs = 25,
    /// Hugging Face Text Generation Inference (TGI) as the CCAI service provider
    /// <a href="<https://github.com/huggingface/text-generation-inference">Text> Generation Inference</a>
    HuggingfaceTgi = 26,
    /// Hugging Face Text Embedding Inference (TGE) as the CCAI service provider
    /// <a href="<https://github.com/huggingface/text-embeddings-inference">Text> Embeddings Inference</a>
    HuggingfaceTge = 27,
    /// Hugging Face SmolAgents as the CCAI service provider
    /// <a href="<https://github.com/huggingface/smolagents">SmolAgents</a>>
    HuggingfaceSmolagents = 28,
    /// Google Agent Development Kit (ADK) as the CCAI service provider
    /// <a href="<https://google.github.io/adk-docs/">Google> Agent Development Kit (ADK)</a>
    GoogleAgentDevelopmentKit = 29,
    /// Model Context Protocol as the CCAI service provider, enabling integration with services following
    /// the Model Context Protocol standard.
    /// <a href="<https://modelcontextprotocol.io/introduction">MCP</a>>
    ModelContextProtocol = 30,
    /// Opensearch as the CCAI service provider, enabling integration with Opensearch vector database and search services
    /// <a href="<https://opensearch.org/">Opensearch</a>>
    Opensearch = 31,
    /// Grok as the CCAI service provider, commonly used for models such as Grok-1
    /// <a href="<https://grok.x.ai/">Grok</a>>
    Grok = 32,
    /// PostgreSQL as the CCAI service provider, enabling integration with PostgreSQL databases
    /// <a href="<https://www.postgresql.org/">PostgreSQL</a>>
    Postgres = 33,
    /// Microsoft Agent Framework as the CCAI service provider
    /// <a href="<https://github.com/microsoft/agent-framework">Microsoft> Agent Framework</a>
    MicrosoftAgentFramework = 34,
}
