/// Represents the options for views of an intent.
/// An intent can be a sizable object. Therefore, we provide a resource view that
/// does not return training phrases in the response by default.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum IntentView {
    /// Same as INTENT_VIEW_FULL
    Unspecified = 0,
    /// All fields are populated.
    Full = 1,
    /// The only nested structures populated are Contexts and Training phrases.
    /// The Training phrases field is populated with only a few entries and no annotations.
    Partial = 2,
    /// All nested structures are not populated (no training phrases, nor contexts, nor parameters, ...)
    Shallow = 3,
    /// Minimum view including only intent UUID and intent display name
    Minimum = 4,
}
impl IntentView {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            Self::Unspecified => "INTENT_VIEW_UNSPECIFIED",
            Self::Full => "INTENT_VIEW_FULL",
            Self::Partial => "INTENT_VIEW_PARTIAL",
            Self::Shallow => "INTENT_VIEW_SHALLOW",
            Self::Minimum => "INTENT_VIEW_MINIMUM",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "INTENT_VIEW_UNSPECIFIED" => Some(Self::Unspecified),
            "INTENT_VIEW_FULL" => Some(Self::Full),
            "INTENT_VIEW_PARTIAL" => Some(Self::Partial),
            "INTENT_VIEW_SHALLOW" => Some(Self::Shallow),
            "INTENT_VIEW_MINIMUM" => Some(Self::Minimum),
            _ => None,
        }
    }
}
/// Represents the type of intents to filter by in the &quot;List Intents&quot; request
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum IntentCategory {
    /// represent all intents
    AllIntents = 0,
    /// represent the default intents
    DefaultIntents = 1,
    /// represent the user defined (custom) intents
    UserDefinedIntents = 2,
    /// represents the intents that had its end_date elapsed
    DateExpiredIntents = 3,
    /// represents the intents that its start_date began but had not yet expired
    DateActiveIntents = 4,
    /// represent the intents that are still expecting its start_date to begin
    DateUpcomingIntents = 5,
}
