/// Type of Intent algorithm.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum IntentAlgorithms {
    /// By enabling this, a specific intent is triggered if the context and the intent name in the user says is
    /// matched. This can be used for directly triggering &apos;quick reply&apos; button clicks confidence is always &apos;1.0&apos;.
    OndewoIntentExactContextDetector = 0,
    /// exact matching&apos; of user input to user says is used to detect the intent. Confidence is always &apos;1.0&apos; if an
    /// &apos;exact match&apos; is found.
    OndewoIntentExactMatch = 1,
    /// the entity synonym in the user says text is replaced by the entity and &apos;exact matching&apos; of user says text
    /// is performed. Confidence is always &apos;1.0&apos;.
    OndewoIntentNamedExactMatch = 2,
    /// the algorithm computes the similarity of the user input to all user says of all intents.
    OndewoIntentSimilarityMatch = 3,
    /// the entity synonyms in the user says are replaced by their Entity. Text similarity algorithms are then
    /// used to detect the intent.
    OndewoIntentNamedSimilarityMatch = 4,
    /// new language representation model called BERT, which stands for Bidirectional Encoder Representations
    /// from Transformers.BERT is designed to pre-train deep bidirectional representations by jointly conditioning
    /// on both left and right context in all layers. As a result, the pre-trained BERT representations can be
    /// fine-tuned for multi-class intent detection. For details see <a href="<https://arxiv.org/abs/1810.04805">https://arxiv.org/abs/1810.04805</a>>
    OndewoIntentBertClassifier = 7,
    /// Meta classifier that combines multiple intent classification algorithms to improve accuracy
    OndewoIntentMetaClassifier = 8,
    /// Maximum number of repeated fallbacks before this algorithm exists the conversation and resets contexts
    IntentExitDetector = 10,
    /// Algorithm to improve the interplay of the other algorithms
    OndewoIntentRankingMatch = 11,
    /// Ensemble calculation of used algorithms
    OndewoWeightedEnsemble = 13,
    /// Maximum number of repeated fallbacks before this algorithm exists the conversation and resets contexts
    OndewoIntentExitDetector = 14,
    /// Matches the intent based on the parameter constellation and the current user context
    OndewoIntentParameterMatch = 15,
}
impl IntentAlgorithms {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            Self::OndewoIntentExactContextDetector => "OndewoIntentExactContextDetector",
            Self::OndewoIntentExactMatch => "OndewoIntentExactMatch",
            Self::OndewoIntentNamedExactMatch => "OndewoIntentNamedExactMatch",
            Self::OndewoIntentSimilarityMatch => "OndewoIntentSimilarityMatch",
            Self::OndewoIntentNamedSimilarityMatch => "OndewoIntentNamedSimilarityMatch",
            Self::OndewoIntentBertClassifier => "OndewoIntentBertClassifier",
            Self::OndewoIntentMetaClassifier => "OndewoIntentMetaClassifier",
            Self::IntentExitDetector => "IntentExitDetector",
            Self::OndewoIntentRankingMatch => "OndewoIntentRankingMatch",
            Self::OndewoWeightedEnsemble => "OndewoWeightedEnsemble",
            Self::OndewoIntentExitDetector => "OndewoIntentExitDetector",
            Self::OndewoIntentParameterMatch => "OndewoIntentParameterMatch",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "OndewoIntentExactContextDetector" => Some(Self::OndewoIntentExactContextDetector),
            "OndewoIntentExactMatch" => Some(Self::OndewoIntentExactMatch),
            "OndewoIntentNamedExactMatch" => Some(Self::OndewoIntentNamedExactMatch),
            "OndewoIntentSimilarityMatch" => Some(Self::OndewoIntentSimilarityMatch),
            "OndewoIntentNamedSimilarityMatch" => Some(Self::OndewoIntentNamedSimilarityMatch),
            "OndewoIntentBertClassifier" => Some(Self::OndewoIntentBertClassifier),
            "OndewoIntentMetaClassifier" => Some(Self::OndewoIntentMetaClassifier),
            "IntentExitDetector" => Some(Self::IntentExitDetector),
            "OndewoIntentRankingMatch" => Some(Self::OndewoIntentRankingMatch),
            "OndewoWeightedEnsemble" => Some(Self::OndewoWeightedEnsemble),
            "OndewoIntentExitDetector" => Some(Self::OndewoIntentExitDetector),
            "OndewoIntentParameterMatch" => Some(Self::OndewoIntentParameterMatch),
            _ => None,
        }
    }
}
